sp_widget.client_script:
api.controller=function($scope) {
  /* widget controller */
  var c = this;

	// Estado inicial (pode ser null, true ou false)
$scope.isLowercase = null;

// Escuta evento do rootScope para atualizar o estado
$scope.$root.$on('toggleCaseEvent', function(event, isLowercase) {
  $scope.isLowercase = isLowercase;
});

};

sp_widget.css:
/* Base Styles */


html, body {
  	font-family: 'Roboto Flex', sans-serif !important;
  	font-weight: 400;
    height: 100%;
    margin: 0;
    display: flex;
    flex-direction: column;
}

.portal-footer {
  	font-family: 'Roboto Flex', sans-serif !important;
  	font-weight: 400;
    background-color: #293273;
    width: 100%;
    min-height: 175px; 
    padding: 20px 0;
    color: white;
    text-align: center;
    margin-top: auto;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.footer-container {
  font-family: 'Roboto Flex', sans-serif !important;
  font-weight: 400;
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    max-width: 1400px;
    margin: 0 auto;
    width: 100%;
    padding: 0 20px;
    box-sizing: border-box;
}

.footer-left {
    font-family: 'Roboto Flex', sans-serif !important;
  font-weight: 400;
    display: flex;
    align-items: flex-start;
    gap: 1rem;
}

.center-img {
    display: block;
    height: auto;
    margin-top: 0;
    max-width: 100%;
    width: 320px;
}

.footer-column {
    margin-left: 0;
    padding: 0 10px;
}

.footer-column h3 {
    font-family: 'Roboto Flex', sans-serif !important;
    font-weight: 400;
    font-size: 22px;
    letter-spacing: 1px;
    line-height: 100%;
    color: white;
    margin-bottom: 12px;
    white-space: pre-line;
    margin-top: 0;
}

.footer-column ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.footer-column ul li {
    margin-bottom: 5px;
    font-size: 13px;
    letter-spacing: 1px;
}

.footer-column ul li a {
    font-family: 'Roboto', sans-serif;
    font-size: 13px;
    letter-spacing: 1px;
    color: white;
    text-decoration: none;
}

.footer-column ul li a:hover {
    text-decoration: underline;
}

.right {
    margin-left: auto;
    text-align: left;
}

.right h4 {
    font-size: 28px;
    margin-bottom: 10px;
    color: #F9F9F9;
}

.right p {
    margin: 2px 0;
    font-size: 14px;
    color: #CBCBCB;
}

.right a {
    color: white;
    text-decoration: none;
}

.contact-info {
    display: flex;
    flex-direction: column;
}

.contact-item {
    display: flex;
    align-items: center;
    margin: 5px 0;
}

.contact-item i {
    margin-right: 10px;
}

.contact-item a {
    color: white;
    text-decoration: none;
}

/* Specific Device Media Queries */

/* Surface Duo (540 x 720) */
@media screen and (width: 540px) {
    .footer-container {
        flex-direction: column;
        align-items: center;
    }

    .center-img {
        width: 220px;
        margin: 10px auto;
    }

    .footer-left {
        flex-direction: column;
        align-items: center;
        width: 100%;
        margin-bottom: 20px;
    }

    .footer-column {
        margin: 10px 0;
        text-align: center;
    }

    .right {
        margin-left: 0;
        text-align: center;
    }
}

.lowercase-text {
  text-transform: lowercase;
}

.uppercase-text {
  text-transform: uppercase;
}


/* iPhone SE (375 x 667) */
@media screen and (width: 375px) {
    .portal-footer {
        padding: 15px 0;
    }

    .footer-container {
        flex-direction: column;
        align-items: center;
    }

    .center-img {
        width: 180px;
        margin: 10px auto;
    }

    .footer-left {
        flex-direction: column;
        align-items: center;
        width: 100%;
    }

    .footer-column h3 {
        font-size: 16px;
        margin-top: 10px;
    }

    .footer-column ul li,
    .footer-column ul li a {
        font-size: 11px;
    }

    .right {
        margin: 15px 0 0 0;
        text-align: center;
    }

    .right h4 {
        font-size: 20px;
    }

    .contact-item {
        justify-content: center;
    }
}

/* iPhone XR (414 x 896) */
@media screen and (width: 414px) {
    .footer-container {
        flex-direction: column;
        align-items: center;
    }

    .center-img {
        width: 200px;
    }

    .footer-left {
        flex-direction: column;
        align-items: center;
    }

    .footer-column h3 {
        font-size: 18px;
    }

    .right {
        margin: 20px 0 0 0;
        text-align: center;
    }

    .contact-item {
        justify-content: center;
    }
}

/* iPhone 12 Pro (390 x 844) */
@media screen and (width: 390px) {
    .footer-container {
        flex-direction: column;
        align-items: center;
    }

    .center-img {
        width: 190px;
    }

    .footer-left {
        flex-direction: column;
        align-items: center;
    }

    .footer-column h3 {
        font-size: 17px;
    }

    .right {
        margin: 20px 0 0 0;
        text-align: center;
    }
}

/* iPhone 14 Pro Max (430 x 932) */
@media screen and (width: 430px) {
    .footer-container {
        flex-direction: column;
        align-items: center;
    }

    .center-img {
        width: 210px;
    }

    .footer-left {
        flex-direction: column;
        align-items: center;
    }

    .footer-column h3 {
        font-size: 18px;
    }

    .right {
        margin: 20px 0 0 0;
        text-align: center;
    }
}

/* Pixel 7 (412 x 915) & Galaxy S20 Ultra (412 x 915) */
@media screen and (width: 412px) {
    .footer-container {
        flex-direction: column;
        align-items: center;
    }

    .center-img {
        width: 200px;
    }

    .footer-left {
        flex-direction: column;
        align-items: center;
    }

    .footer-column h3 {
        font-size: 18px;
    }

    .right {
        margin: 20px 0 0 0;
        text-align: center;
    }
}

/* Galaxy S8+ (360 x 740) */
@media screen and (width: 360px) {
    .footer-container {
        flex-direction: column;
        align-items: center;
    }

    .center-img {
        width: 180px;
    }

    .footer-left {
        flex-direction: column;
        align-items: center;
    }

    .footer-column h3 {
        font-size: 16px;
    }

    .footer-column ul li,
    .footer-column ul li a {
        font-size: 11px;
    }

    .right {
        margin: 15px 0 0 0;
