    }

    .footer-column {
        text-align: center;
        min-width: 200px;
    }

    .right {
        margin: 10px 0 0 0;
        text-align: center;
    }

    .contact-item {
        justify-content: center;
    }
}

/* iPad Air (820 x 1180) */
@media screen and (width: 820px) {
    .footer-container {
        flex-direction: column;
        align-items: center;
        padding: 0 40px;
    }

    .center-img {
        width: 270px;
        margin: 20px auto;
    }

    .footer-left {
        flex-direction: row;
        flex-wrap: wrap;
        justify-content: center;
        gap: 40px;
        margin-bottom: 25px;
    }

    .footer-column {
        text-align: center;
        min-width: 220px;
    }

    .right {
        margin: 15px 0 0 0;
        text-align: center;
    }
}

/* Surface Pro 7 (912 x 1368) */
@media screen and (width: 912px) {
    .footer-container {
        flex-direction: row;
