        align-items: center;
        width: 60%;
        gap: 20px;
    }

    .footer-column {
        text-align: left;
        min-width: 160px;
    }

    .right {
        width: 30%;
        margin-left: auto;
        text-align: left;
    }
}

/* Asus Zenbook Fold (853 x 1280) */
@media screen and (width: 853px) {
    .footer-container {
        flex-direction: row;
        flex-wrap: wrap;
        justify-content: space-between;
        align-items: flex-start;
        padding: 0 30px;
    }

    .center-img {
        width: 250px;
        margin: 0;
    }

    .footer-left {
        flex: 1;
        flex-direction: row;
        flex-wrap: wrap;
        justify-content: space-around;
        gap: 20px;
    }

    .footer-column {
        min-width: 150px;
        text-align: left;
    }

    .right {
        width: 30%;
        margin-left: auto;
        text-align: left;
    }
}

/* Range-based media queries for better coverage */

/* Extra Small Devices (phones) */
@media screen and (max-width: 480px) {
    .portal-footer {
        min-height: auto;
        padding: 15px 0;
    }

    .footer-container {
        flex-direction: column;
        align-items: center;
    }

    .center-img {
        max-width: 180px;
    }

    .footer-left {
        flex-direction: column;
        align-items: center;
        width: 100%;
    }

    .footer-column {
        margin: 10px 0;
        text-align: center;
    }

    .footer-column h3 {
        font-size: 16px;
    }

    .footer-column ul li,
    .footer-column ul li a {
        font-size: 11px;
    }

    .right {
        margin: 15px 0 0 0;
        text-align: center;
        width: 100%;
    }

    .right h4 {
        font-size: 20px;
    }

    .contact-item {
        justify-content: center;
    }
}

/* Small Devices (large phones, small tablets) */
@media screen and (min-width: 481px) and (max-width: 767px) {
    .footer-container {
        flex-direction: column;
        align-items: center;
    }

    .center-img {
        max-width: 220px;
        margin: 10px auto;
    }

    .footer-left {
        flex-direction: column;
        align-items: center;
        width: 100%;
    }

    .footer-column {
        margin: 10px 0;
        text-align: center;
    }

    .right {
        margin: 20px 0 0 0;
        text-align: center;
        width: 100%;
    }

    .contact-item {
        justify-content: center;
    }
}

/* Medium Devices (tablets) */
@media screen and (min-width: 768px) and (max-width: 991px) {
    .footer-container {
        flex-direction: column;
        align-items: center;
    }

    .center-img {
        max-width: 260px;
        margin: 20px auto;
    }

    .footer-left {
        flex-direction: row;
        flex-wrap: wrap;
        justify-content: center;
        gap: 30px;
        margin-bottom: 20px;
    }

    .footer-column {
        text-align: center;
        min-width: 200px;
    }

    .right {
        margin: 15px 0 0 0;
        text-align: center;
        width: 100%;
    }

    .contact-item {
        justify-content: center;
    }
}

/* Large Devices (desktops, laptops) */
@media screen and (min-width: 992px) and (max-width: 1199px) {
    .footer-container {
        flex-direction: row;
        align-items: flex-start;
        padding: 0 30px;
    }

    .center-img {
        width: 260px;
        margin: 0;
    }

    .footer-left {
        flex-direction: row;
        flex-wrap: wrap;
        justify-content: flex-start;
        gap: 20px;
        width: 60%;
    }

    .footer-column {
        min-width: 150px;
    }

    .right {
        width: 30%;
        margin-left: auto;
        text-align: left;
    }
}

/* Extra Large Devices (large desktops) */
@media screen and (min-width: 1200px) {
    .footer-container {
        padding: 0 40px;
    }

    .center-img {
        width: 320px;
    }

    .footer-left {
        gap: 2rem;
    }

    .footer-column {
        min-width: 180px;
    }

    .right {
        width: 25%;
    }
}

/* Extra Extra Large Devices */
@media screen and (min-width: 1700px) {
    .footer-column {
        flex: 1;
        margin-left: 0px;
        margin-bottom: -18px;
    }

    .footer-left {
        display: flex;
        align-items: center;
        gap: 1rem;
        margin: 0;
        padding: 2rem 0;
      	transform: translate(105px, 34px);
    }

    .right {
        margin-left: auto;
        text-align: left;
        width: 25%;
    }

    .center-img {
        display: block;
        height: auto;
        margin-top: -0.8rem;
        max-width: 100%;
    }
    .contact-info{
    transform: translateX(380px);
  }
  .right h4{
    transform: translateX(380px);
  }

}

/* High Density Displays */
@media (min-resolution: 1.25dppx), (min-scale: 1.25) {
    .footer-container {
        max-width: 100%;
    }

    .center-img {
        max-width: 300px;
    }
}
